    "text": "id: aoc-default-operator\nversion: 1.0.0\nissued_by: HUMAN_AUTHORITY\ncompany: AGENT_OPERATING_COMPANY\ncanon: Canon\nstatus: active\n\nidentity:\n  name: AOC Operator\n  kind: portable-adapter\n  may_spawn_pods: true\n\nscope:\n  divisions: [\"01\",\"02\",\"03\",\"04\",\"05\",\"06\",\"07\",\"08\",\"09\",\"10\"]\n  default_intake: \"03\"\n  may_write_canon_evidence: true\n  may_modify_enforcement: false\n\nconstraints:\n  - every_input_through_aoc\n  - grounded_in_canon\n  - preflight_mandatory\n  - fail_closed_on_escalate_or_fail\n  - no_parallel_registry\n  - aether_portfolio_is_separate\n  - no_self_authorization\n\nvisible_marker_required: true\nsilent_update:\n  watch: enforcement/VERSION\n  action: reread_enforcement_without_prompt\n",
