    "text": "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://canon.aoc/enforcement/PREFLIGHT-RECEIPT.schema.json\",\n  \"title\": \"PreflightReceipt\",\n  \"type\": \"object\",\n  \"additionalProperties\": false,\n  \"required\": [\n    \"version\", \"schema\", \"id\", \"timestamp\", \"input_digest\", \"input_summary\",\n    \"routed_to\", \"checks\", \"decision\", \"fail_closed\", \"work_permitted\",\n    \"status_marker\", \"notes\", \"enforcement_version\"\n  ],\n  \"properties\": {\n    \"version\": { \"const\": \"1.0.0\" },\n    \"schema\": { \"const\": \"canon.preflight.receipt\" },\n    \"id\": { \"type\": \"string\", \"minLength\": 8 },\n    \"timestamp\": { \"type\": \"string\" },\n    \"input_digest\": { \"type\": \"string\" },\n    \"input_summary\": { \"type\": \"string\" },\n    \"routed_to\": {\n      \"type\": \"object\",\n      \"required\": [\"authority\", \"company\", \"division_id\", \"division_name\", \"canon_refs\", \"roles\"],\n      \"properties\": {\n        \"authority\": { \"const\": \"HUMAN_AUTHORITY\" },\n        \"company\": { \"const\": \"AGENT_OPERATING_COMPANY\" },\n        \"division_id\": { \"type\": \"string\" },\n        \"division_name\": { \"type\": \"string\" },\n        \"canon_refs\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n        \"roles\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }\n      }\n    },\n    \"checks\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"object\",\n        \"required\": [\"id\", \"name\", \"result\", \"detail\"],\n        \"properties\": {\n          \"id\": { \"type\": \"string\" },\n          \"name\": { \"type\": \"string\" },\n          \"result\": { \"enum\": [\"pass\", \"fail\", \"warn\"] },\n          \"detail\": { \"type\": \"string\" }\n        }\n      }\n    },\n    \"decision\": { \"enum\": [\"PASS\", \"ESCALATE\", \"FAIL\"] },\n    \"fail_closed\": { \"type\": \"boolean\" },\n    \"work_permitted\": { \"type\": \"boolean\" },\n    \"status_marker\": {\n      \"type\": \"string\",\n      \"pattern\": \"^\\\\[AOC/Canon • Preflight (PASS|ESCALATE|FAIL)\\\\]$\"\n    },\n    \"notes\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n    \"enforcement_version\": { \"type\": \"string\" }\n  }\n}\n",
